left join public.brands b on b.name = x->>'brand'
left join public.categories c on c.path = array(select jsonb_array_elements_text(x->'category_path'))
on conflict (sku) do update set
  name = excluded.name,
  brand_id = excluded.brand_id,
  category_id = excluded.category_id,
  category_path = excluded.category_path,
  description = excluded.description,
  price_cents = excluded.price_cents,
  compare_at_price_cents = excluded.compare_at_price_cents,
  stock = excluded.stock,
  cover_path = excluded.cover_path,
  metadata = excluded.metadata,
  updated_at = now();

-- products 1360-1440
insert into public.products (
  sku, name, brand_id, category_id, category_path, description,
  price_cents, compare_at_price_cents, stock, cover_path, metadata
)
select
  x->>'sku',
  x->>'name',
  b.id,
  c.id,
  coalesce(array(select jsonb_array_elements_text(x->'category_path')), '{}'),
  coalesce(x->>'description', ''),
  coalesce((x->>'price_cents')::int, 0),
  nullif(x->>'compare_at_price_cents', '')::int,
  coalesce((x->>'stock')::int, 0),
  nullif(x->>'cover_path', ''),
  jsonb_build_object('source', 'cabesto-catalog')
from jsonb_array_elements($json$[{"sku":"SU-0001915","name":"Compas poignet de plongée sous-marine AQUATYS","brand":"AQUATYS","category_path":["plongee","1er-prix-club-association"],"description":"Compas de Poignet Axess : précision et fiabilité pour vos plongéesUn instrument essentiel pour une navigation sous-marine précise et sécurisée.Le compas de poignet Axess est conçu pour les plongeurs exigeants qui recherchent un outil fiable et précis pour s'orienter sous l'eau. Doté d'un cadran phosphorescent haute visibilité, il garantit une lecture facile même dans des conditions de faible luminosité. Sa capsule remplie de liquide assure une stabilité optimale de l'aiguille, permettant une navigation précise à tout moment. Le bracelet ajustable en silicone offre un confort maximal et s'adapte à toutes les tailles de poignet. Compact et léger, ce compas est idéal pour les plongées récréatives ou techniques. Grâce à sa robustesse et à sa conception ergonomique, le compas de poignet Axess est un compagnon indispensable pour explorer les fonds marins en toute sérénité.Caractéristiques Compas de Poignet AxessCadran phosphorescent pour une lecture facileCapsule remplie de liquide pour une stabilité optimaleBracelet ajustable en silicone pour un confort maximalCompact et léger pour une utilisation pratiqueConception robuste et ergonomiqueInformations techniques :MatériauSilicone et plastique haute résistancePoids120 gType de cadranPhosphorescentRemplissageLiquide stabilisantUtilisationNavigation sous-marineContenu du colis1 compas de poignet Axess avec bracelet ajustable en silicone.","price_cents":3599,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0001915/01-boussole-de-poignet-best-divers_pzlurvpl1dg1ntnq.jpg"},{"sku":"SU-0001916","name":"Compas de plongée sous-marine FS2 avec rétracteur SCUBAPRO","brand":"Cabesto","category_path":["plongee","plongee-sous-marine","instruments-de-plongee"],"description":"FS2 est le premier compas qui accepte n'importe quel angle avec l'horizontal en donnant toujours le nord.C'est un compas à bain d'huile avec boitier en polycarbonate.Sa fenêtre de vision est latérale pour une navigation facile et préciseIl dipose d'un graduation par paliers de 10° pour une navigation précise.Enfin, son cadran est très lumineux pour une meilleure lisibilité","price_cents":12900,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0001916/02-pl-295-pl-295-picture_2-pl-295-2.jpg"},{"sku":"SU-0001918","name":"Compas de plongée sous-marine FS2 seul pour rétracteur SCUBAPRO","brand":"SCUBAPRO","category_path":["plongee","plongee-sous-marine","instruments-de-plongee"],"description":"FS2 est le premier compas qui accepte n'importe quel angle avec l'horizontal en donnant toujours le nord.C'est un compas à bain d'huile avec boitier en polycarbonate.Sa fenêtre de vision est latérale pour une navigation facile et préciseIl dipose d'un graduation par paliers de 10° pour une navigation précise.Enfin, son cadran est très lumineux pour une meilleure lisibilité","price_cents":7999,"compare_at_price_cents":null,"stock":0,"cover_path":"/media/SU-0001918/01-pl-3416-pl-3416-picture_1-pl-3416-1.jpg"},{"sku":"SU-0001921","name":"Compas poignet de plongée sous-marine SK8 bracelet bungee SUUNTO","brand":"SUUNTO","category_path":["plongee","plongee-sous-marine","instruments-de-plongee"],"description":"Trouvez le Nord avec l'excellent compas de poignet sous-marin SUNNTO SK-8 Black Bungee Mount NH, orienté pour l'hémisphère nord, enfin disponible dans sa version bungee corde élastique.","price_cents":7300,"compare_at_price_cents":null,"stock":12,"cover_path":"/media/SU-0001921/02-pl-7011-pl-7011-picture_1-pl-7011-1.jpg"},{"sku":"SU-0001922","name":"Compas poignet de plongée sous-marine SK8 SUUNTO","brand":"SUUNTO","category_path":["plongee","plongee-sous-marine","instruments-de-plongee"],"description":"Angle d'inclinaison : +/-30°Chiffres faciles à lireFenêtre de visée très largeLunette de cap crantéeParfaite prise en